// Interface icons for the app: the same Lucide set as the landing page (src/icons.ts, generated by
// scripts/icons.mjs; ISC, the notice is in that file). Decorative: pair with text or a label.
import { ICONS, type IconName } from "../icons";

export function Icon({ name, className = "icon" }: { name: IconName; className?: string }) {
  return <svg viewBox="0 0 24 24" aria-hidden="true" className={className} dangerouslySetInnerHTML={{ __html: ICONS[name] }} />;
}
